984	                }
985	            }
986	        }
987	        PendingTrigger::BlocksTrigger { object_id, card_id, blocked_attacker, .. } => {
988	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
989	                if let Some(behavior) = registry.get(card_id) {
990	                    behavior.on_blocks(state, object_id, blocked_attacker, registry);
991	                }
992	            }
993	        }
994	        PendingTrigger::AttackWatch { watcher_id, watcher_card_id, attacker_id, attacker_controller, .. } => {
995	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
996	                if let Some(behavior) = registry.get(watcher_card_id) {
997	                    behavior.on_any_creature_attacks(state, watcher_id, attacker_id, attacker_controller, registry);
998	                }
999	            }
1000	        }
1001	        PendingTrigger::BecomesBlockedTrigger { object_id, card_id, blocker_id, .. } => {
1002	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
1003	                if let Some(behavior) = registry.get(card_id) {
1004	                    behavior.on_becomes_blocked(state, object_id, blocker_id, registry);
1005	                }
1006	            }
1007	        }
1008	        PendingTrigger::StateTriggered { object_id, card_id, .. } => {
1009	            // Clear the "on stack" flag so the trigger can fire again if the
1010	            // condition is still true after resolution.
1011	            if let Some(obj) = state.get_object_mut(object_id) {
1012	                obj.state_trigger_on_stack = false;
1013	            }
1014	            // Only resolve if the object is still on the battlefield.
1015	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
1016	                if let Some(behavior) = registry.get(card_id) {
1017	                    behavior.on_state_trigger(state, object_id, registry);
1018	                }
1019	            }
1020	        }
1021	    }
1022	
1023	    true
1024	}
