248	/// Pitchburn Devils deals 3 damage to any target when it dies.
249	#[test]
250	fn pitchburn_devils_deals_3_on_death() {
251	    use mtg_engine::actions::ResolvedChoice;
252	
253	    let reg = registry();
254	    let mut state = game_at_step(Step::PrecombatMain, P0);
255	
256	    let pd = named_creature(&mut state, &reg, "Pitchburn Devils", P0);
257	
258	    // Kill it with lethal damage.
259	    state.get_object_mut(pd).unwrap().damage_marked = 3;
260	    state.events.clear();
261	    check_state_based_actions_with_registry(&mut state, Some(&reg));
262	
263	    assert_eq!(state.get_object(pd).unwrap().zone, Zone::Graveyard);
264	
265	    triggers::process_triggers(&mut state, &reg);
266	
267	    // Should be awaiting a target choice (both players are valid targets).
268	    assert!(state.awaiting_action.is_some(), "Should be awaiting damage target choice");
269	
270	    // Choose opponent as target.
271	    state = engine::submit_action(
272	        &state,
273	        &Action::ResolveChoice { choice: ResolvedChoice::ChosenTarget(Some(Target::Player(P1))) },
274	        &reg,
275	    );
276	
277	    assert_eq!(state.get_player(P1).life, 17,
278	        "Opponent should lose 3 life from Pitchburn Devils dying");
279	}
280	
281	/// Falkenrath Noble drains 1 life whenever any creature dies.
282	#[test]
283	fn falkenrath_noble_drains_on_any_death() {
284	    let reg = registry();
285	    let mut state = game_at_step(Step::PrecombatMain, P0);
286	
287	    // Falkenrath Noble on P0's side.
288	    let _noble = named_creature(&mut state, &reg, "Falkenrath Noble", P0);
289	
290	    // A creature on P0's side to kill (Noble triggers on any creature dying).
291	    let victim = ready_creature(&mut state, P0, 1, 1);
292	
293	    // Kill the victim.
294	    state.get_object_mut(victim).unwrap().damage_marked = 1;
295	    state.events.clear();
296	    check_state_based_actions_with_registry(&mut state, Some(&reg));
297	
298	    assert_eq!(state.get_object(victim).unwrap().zone, Zone::Graveyard);
299	
300	    triggers::process_triggers(&mut state, &reg);
301	
302	    assert_eq!(state.get_player(P1).life, 19,
303	        "P1 should lose 1 life from Falkenrath Noble's trigger");
304	    assert_eq!(state.get_player(P0).life, 21,
305	        "P0 should gain 1 life from Falkenrath Noble's trigger");
306	}
